def _master_split_rdata_txt(remainder):
    """扫描记录行 TYPE 之后的 TXT rdata 子串为逐字节串列表。

    子串以 ASCII 空白分词，但双引号串可跨越空白；仅接受可打印 ASCII
    （0x20..0x7E）与空白分隔，转义仅为 \\\\、\\" 或三位十进制 \\DDD
    （000..255），引号必须配对且串至少一个、至多 255 个，每段解码后
    1..255 字节。空引号串、引号内空白、非引号转义（如空格的 \\DDD）
    均按段内容保留。语法层错误（字段数、引号、转义）抛 ConfigError；
    段数/段长越界属字段限制亦抛 ConfigError。"""
    strings = []
    pos = 0
    length = len(remainder)
    while True:
        while pos < length and remainder[pos] in _MASTER_WHITESPACE:
            pos += 1
        if pos >= length:
            break
        segment = bytearray()
        if remainder[pos] == '"':
            pos += 1
            while True:
                if pos >= length:
                    raise ConfigError("unterminated quoted string")
                ch = remainder[pos]
                if ch == '"':
                    pos += 1
                    break
                if ch == "\\":
                    segment, pos = _master_read_escape(remainder, pos)
                    continue
                if ch in _MASTER_WHITESPACE or not (
                        " " <= ch <= "~"):
                    raise ConfigError("invalid TXT character")
                segment.append(ord(ch))
                pos += 1
        else:
            while pos < length and remainder[pos] not in _MASTER_WHITESPACE:
                ch = remainder[pos]
                if ch == '"':
                    raise ConfigError("unexpected quote in TXT field")
                if ch == "\\":
                    segment, pos = _master_read_escape(remainder, pos)
                    continue
                if not (" " <= ch <= "~"):
                    raise ConfigError("invalid TXT character")
                segment.append(ord(ch))
                pos += 1
        if not 1 <= len(segment) <= _MAX_TXT_STRING_LEN:
            raise ConfigError("TXT string length must be 1..255")
        strings.append(bytes(segment))
        if len(strings) > _MAX_TXT_STRINGS:
            raise ConfigError("TXT rdata must contain at most 255 strings")
    if not strings:
        raise ConfigError("TXT rdata must contain at least one string")
    return strings

