# -*- coding: utf-8 -*-
import dns
from dns import import_master, export_master, ConfigError, RecordError, ZoneError

SOA = '@ 100 IN SOA @ @ 1 7200 3600 1209600 60'

def zone_text(extra):
    return "$ORIGIN example.\n" + SOA + "\n" + "\n".join(extra) + "\n"

failures = []
def check(fn):
    try:
        fn()
    except Exception as exc:
        failures.append((fn.__name__, repr(exc)))
        print("FAIL", fn.__name__, "->", repr(exc))
    else:
        print("ok  ", fn.__name__)
    return fn

def expect(exc_type):
    def deco(fn):
        def wrap():
            try:
                fn()
            except exc_type:
                return
            raise AssertionError("expected %s" % exc_type.__name__)
        wrap.__name__ = fn.__name__
        return wrap
    return deco

# ---------- basic import: wire encodings ----------
@check
def wire_ns():
    z = import_master(zone_text([
        "@ 100 IN NS @",
        "@ 100 IN NS ns1.example.",
        "sub.example. 200 IN NS ns2.other.",
    ]))
    assert list(z.keys()) == ["origin", "records"]
    assert z["origin"] == "example."
    by_name = {}
    for r in z["records"]:
        by_name.setdefault((r["name"], r["type"]), []).append(r)
    at = by_name[("example.", 2)][0]
    assert at["rdata"] == b"\x07example\x00", at["rdata"].hex()
    assert (at["class"], at["ttl"]) == (1, 100)
    assert list(at.keys()) == ["name", "type", "class", "ttl", "rdata"]
    assert by_name[("example.", 2)][1]["rdata"] == b"\x03ns1\x07example\x00"
    assert by_name[("sub.example.", 2)][0]["rdata"] == b"\x03ns2\x05other\x00"

@check
def wire_mx():
    z = import_master(zone_text([
        "@ 100 IN MX 10 @",
        "@ 100 IN MX 00020 mail.example.",
        "@ 100 IN MX 65535 mx2.example.",
    ]))
    mxs = [r for r in z["records"] if r["type"] == 15]
    assert mxs[0]["rdata"] == b"\x00\x0a\x07example\x00", mxs[0]["rdata"].hex()
    assert mxs[1]["rdata"] == b"\x00\x14\x04mail\x07example\x00"
    assert mxs[2]["rdata"] == b"\xff\xff\x03mx2\x07example\x00"
    assert mxs[2]["name"] == "example." and mxs[2]["ttl"] == 100

@check
def wire_txt():
    z = import_master(zone_text([
        '@ 100 IN TXT "hello"',
        '@ 100 IN TXT "two" "segments"',
        '@ 100 IN TXT ""',
        r'@ 100 IN TXT "a\\b\"c\000d\255"',
        '@ 100 IN TXT "with space inside"',
    ]))
    txts = [r for r in z["records"] if r["type"] == 16]
    assert txts[0]["rdata"] == b"\x05hello", txts[0]["rdata"]
    assert txts[1]["rdata"] == b"\x03two\x08segments"
    assert txts[2]["rdata"] == b"\x00"
    assert txts[3]["rdata"] == b"\x08a\\b\"c\x00d\xff", txts[3]["rdata"]
    assert txts[4]["rdata"] == b"\x12with space inside"

# ---------- record order & keys ----------
@check
def order_preserved():
    lines = [
        '@ 100 IN MX 10 mail.example.',
        '@ 100 IN NS ns1.example.',
        'host.example. 60 IN A 192.0.2.1',
        '@ 100 IN TXT "v=spf1 -all"',
        '@ 100 IN NS ns2.example.',
    ]
    z = import_master(zone_text(lines))
    types = [(r["name"], r["type"]) for r in z["records"]]
    assert types == [("example.", 6), ("example.", 15), ("example.", 2),
                     ("host.example.", 1), ("example.", 16),
                     ("example.", 2)], types

# ---------- round trip & byte identity ----------
@check
def roundtrip():
    text = zone_text([
        '@ 300 IN NS ns1.example.',
        '@ 300 IN NS @',
        '@ 300 IN MX 10 mail.example.',
        '@ 300 IN MX 0 @',
        'host.example. 60 IN A 192.0.2.9',
        'host6.example. 60 IN AAAA 2001:db8::1',
        'www.example. 60 IN CNAME host.example.',
        '*.wild.example. 60 IN TXT "wc" "x"',
        r'@ 60 IN TXT "q\" b" "p\\q" "\000\001\127\200\255" ""',
    ])
    z1 = import_master(text)
    out1 = export_master(z1)
    assert out1 == export_master(import_master(out1))
    assert out1 == export_master(z1)
    assert import_master(out1) == z1
    assert out1 == text, "\n%r\n%r" % (out1, text)

@check
def leading_zero_preference_normalized():
    text = zone_text(['@ 100 IN MX 00010 mail.example.'])
    out = export_master(import_master(text))
    assert "@ 100 IN MX 10 mail.example.\n" in out

@check
def txt_nonprintable_export():
    z = import_master(zone_text([r'@ 100 IN TXT "\000\009\013\032\126\127\255"']))
    out = export_master(z)
    expected = r'@ 100 IN TXT "\000\009\013\032~\127\255"' + "\n"
    assert expected in out, repr(out)
    z2 = import_master(zone_text([r'@ 100 IN TXT "\\\""']))
    out2 = export_master(z2)
    assert r'@ 100 IN TXT "\\\""' + "\n" in out2, repr(out2)
    # every byte 0..255 round-trips through quoting
    z3 = import_master(zone_text([r'@ 100 IN TXT "\000\001\002"']))
    rr = [r for r in z3["records"] if r["type"] == 16][0]
    # build rdata covering all 256 byte values in 2 segments
    seg = bytes(range(256))
    z4 = {"origin": "example.", "records": [
        {"name": "example.", "type": 6, "class": 1, "ttl": 100,
         "rdata": b"\x07example\x00\x07example\x00"
                  + b"".join(x.to_bytes(4, "big") for x in (1, 2, 3, 4, 60))},
        {"name": "example.", "type": 16, "class": 1, "ttl": 100,
         "rdata": bytes((255,)) + seg[:255] + bytes((1,)) + seg[255:]}]}
    out4 = export_master(z4)
    z5 = import_master(out4)
    assert [r for r in z5["records"] if r["type"] == 16][0]["rdata"] == \
        z4["records"][1]["rdata"]
    assert export_master(z5) == out4

# ---------- errors: ConfigError ----------
@check
@expect(ConfigError)
def ns_two_fields():
    import_master(zone_text(['@ 100 IN NS a.example. b.example.']))

@check
@expect(ConfigError)
def ns_zero_fields():
    import_master(zone_text(['@ 100 IN NS']))

@check
@expect(ConfigError)
def mx_one_field():
    import_master(zone_text(['@ 100 IN MX 10']))

@check
@expect(ConfigError)
def mx_three_fields():
    import_master(zone_text(['@ 100 IN MX 10 a.example. b.example.']))

@check
@expect(ConfigError)
def mx_pref_65536():
    import_master(zone_text(['@ 100 IN MX 65536 mail.example.']))

@check
@expect(ConfigError)
def mx_pref_negative():
    import_master(zone_text(['@ 100 IN MX -1 mail.example.']))

@check
@expect(ConfigError)
def mx_pref_alpha():
    import_master(zone_text(['@ 100 IN MX ten mail.example.']))

@check
@expect(ConfigError)
def txt_unquoted():
    import_master(zone_text(['@ 100 IN TXT hello']))

@check
@expect(ConfigError)
def txt_unterminated():
    import_master(zone_text(['@ 100 IN TXT "abc']))

@check
@expect(ConfigError)
def txt_bad_escape_letter():
    import_master(zone_text([r'@ 100 IN TXT "a\nb"']))

@check
@expect(ConfigError)
def txt_bad_escape_256():
    import_master(zone_text([r'@ 100 IN TXT "\256"']))

@check
@expect(ConfigError)
def txt_bad_escape_999():
    import_master(zone_text([r'@ 100 IN TXT "\999"']))

@check
@expect(ConfigError)
def txt_bad_escape_two_digits():
    import_master(zone_text([r'@ 100 IN TXT "\09"']))

