def txt_segment_too_long_literal():
    import_master(zone_text(['@ 100 IN TXT "' + 'a' * 256 + '"']))

@check
@expect(ConfigError)
def txt_segment_too_long_escapes():
    import_master(zone_text(['@ 100 IN TXT "' + 'a' * 254 + r'\065\066"']))

@check
