def unknown_type_unchanged():
    import_master(zone_text(['@ 100 IN PTR host.example.']))

@check
@expect(ConfigError)
def txt_control_char_in_text():
    import_master("$ORIGIN example.\n" + SOA + '\n@ 100 IN TXT "a\x7fb"\n')

# ---------- errors: RecordError (names) ----------
@check
@expect(RecordError)
def ns_uppercase():
    import_master(zone_text(['@ 100 IN NS NS1.example.']))

@check
