@check
def roundtrip():
    text = zone_text([
        '@ 300 IN NS ns1.example.',
        '@ 300 IN NS @',
        '@ 300 IN MX 10 mail.example.',
        '@ 300 IN MX 0 @',
        'host.example. 60 IN A 192.0.2.9',
        'host6.example. 60 IN AAAA 2001:db8::1',
        'www.example. 60 IN CNAME host.example.',
        '*.wild.example. 60 IN TXT "wc" "x"',
