    ])
    z1 = import_master(text)
    out1 = export_master(z1)
    assert out1 == export_master(import_master(out1))
    assert out1 == export_master(z1)
    assert import_master(out1) == z1
    assert out1 == text, "\n%r\n%r" % (out1, text)

