# ---------- answer() can serve new types ----------
@check
def answer_txt_ns_mx():
    z = import_master(zone_text([
        '@ 100 IN NS ns1.example.',
        '@ 100 IN MX 10 mail.example.',
        '@ 100 IN TXT "v=spf1 -all"',
        'ns1.example. 100 IN A 192.0.2.2',
        'mail.example. 100 IN A 192.0.2.3',
    ]))
    def query(name, qtype):
        labels = b"".join(bytes([len(l)]) + l.encode()
                          for l in name[:-1].split(".")) + b"\x00"
        return (b"\xab\xcd\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00"
                + labels + qtype.to_bytes(2, "big") + b"\x00\x01")
    for ty in (16, 15, 2):
        pkt = dns.answer(query("example.", ty), z, 512)
        assert pkt[0:2] == b"\xab\xcd" and pkt[7] >= 1, pkt.hex()
        # ancount type matches
        ancount = int.from_bytes(pkt[6:8], "big")
        assert ancount >= 1

